class Counter {
  count = 0;
  step = this.count + 1;

  up = () => {
    this.count += this.step;

    return this.count;
  };

  down() {
    return this.count - this.step;
  }
}

const a = new Counter();
const b = new Counter();
const sameUp = a.up === b.up;

b.up = a.up;

console.log(b.up());
console.log(b.up());
console.log(a.count, b.count);
console.log(sameUp, a.down === b.down);
